#include <stdio.h>
#include <stdlib.h>

typedef struct BiTNode {
    char data;
    struct BiTNode *lchild, *rchild;
} BiTNode, *BiTree;

/* 按先序扩展序列建树，'#' 表示空子树 */
static void CreateBiTree(BiTree *T, const char *s, int *k) {
    if (s[*k] == '#') { (*k)++; *T = NULL; return; }
    *T = (BiTNode *)malloc(sizeof(BiTNode));
    if (*T == NULL) { *T = NULL; printf("malloc failed\n"); return; }
    (*T)->data = s[*k];
    (*k)++;
    (*T)->lchild = NULL;
    (*T)->rchild = NULL;
    CreateBiTree(&(*T)->lchild, s, k);
    CreateBiTree(&(*T)->rchild, s, k);
}

static int ipow2(int e) {
    int v = 1, i;
    for (i = 0; i < e; i++) { v *= 2; }
    return v;
}

static void Count(const BiTree T, int *n0, int *n1, int *n2, int *depth) {
    int dl = 0, dr = 0;
    if (T == NULL) { *depth = 0; return; }
    if (T->lchild == NULL && T->rchild == NULL) { (*n0)++; }
    else if (T->lchild == NULL || T->rchild == NULL) { (*n1)++; }
    else { (*n2)++; }
    Count(T->lchild, n0, n1, n2, &dl);
    Count(T->rchild, n0, n1, n2, &dr);
    *depth = (dl > dr ? dl : dr) + 1;
}

static void Destroy(BiTree T) {
    if (T == NULL) { return; }
    Destroy(T->lchild);
    Destroy(T->rchild);
    free(T);
}

int main(void) {
    const char *cases[2];
    int t;
    cases[0] = "ABD##E##CF##G##";
    cases[1] = "A#CD###";

    for (t = 0; t < 2; t++) {
        BiTree T = NULL;
        int k = 0, n0 = 0, n1 = 0, n2 = 0, depth = 0, total;
        CreateBiTree(&T, cases[t], &k);
        Count(T, &n0, &n1, &n2, &depth);
        total = n0 + n1 + n2;
        printf("先序扩展序列：%s\n", cases[t]);
        printf("  n0=%d n1=%d n2=%d 总结点=%d 深度=%d\n", n0, n1, n2, total, depth);
        printf("  性质3：n0 = n2 + 1 → %d = %d + 1 → %s\n",
               n0, n2, (n0 == n2 + 1) ? "成立" : "不成立");
        printf("  性质2：结点数 %d <= 2^%d - 1 = %d → %s\n\n",
               total, depth, ipow2(depth) - 1,
               (total <= ipow2(depth) - 1) ? "成立" : "不成立");
        Destroy(T);
    }
    return 0;
}

#include <stdio.h>

/* floor(log2 n)，用整数循环实现，避免依赖 libm */
static int floorLog2(int n) {
    int k = 0;
    while (n > 1) { n /= 2; k++; }
    return k;
}

static int ipow2(int e) {
    int v = 1, i;
    for (i = 0; i < e; i++) { v *= 2; }
    return v;
}

int main(void) {
    int n = 12, i, k, depth;

    printf("完全二叉树：n = %d，编号 1..%d\n\n", n, n);
    printf("%-5s%-9s%-9s%-9s%-8s%-8s\n",
           "i", "parent", "lchild", "rchild", "lsib", "rsib");
    for (i = 1; i <= n; i++) {
        int p  = (i == 1) ? 0 : i / 2;
        int lc = (2 * i > n) ? 0 : 2 * i;
        int rc = (2 * i + 1 > n) ? 0 : 2 * i + 1;
        int ls = (i == 1 || i % 2 == 1) ? 0 : i - 1;
        int rs = (i == n || i % 2 == 0) ? 0 : i + 1;
        printf("%-5d%-9d%-9d%-9d%-8d%-8d\n", i, p, lc, rc, ls, rs);
    }

    depth = floorLog2(n) + 1;
    printf("\n性质4：深度 = floor(log2(%d)) + 1 = %d\n", n, depth);
    printf("性质1：各层最多结点数 → ");
    for (k = 1; k <= depth; k++) { printf("L%d<=%d  ", k, ipow2(k - 1)); }
    printf("\n性质2：深度 %d 的二叉树最多 %d 个结点\n", depth, ipow2(depth) - 1);
    return 0;
}

