## 一、顺序存储结构

用一维数组，按完全二叉树的编号规则依次存放：编号 i 的结点存于 data[i-1]（若 0 号单元不用，则存于 data[i]）。

```c
#define MAX_TREE_SIZE 100
typedef char SqBiTree[MAX_TREE_SIZE];   /* 0 号单元可存根结点个数 */
```

- 优点：满二叉树、完全二叉树最省空间；由编号可直接算出双亲与孩子（性质 5），不需要指针
- 缺点：一般二叉树必须先补成完全二叉树，最坏情况是**深度为 k 的单支树**——只有 k 个结点，却要分配 2^k - 1 个单元
- 适用：满二叉树、完全二叉树、堆

例：深度 5 的右单支树只有 5 个结点，但按编号它们落在 1、3、7、15、31，需要 31 个单元，利用率约 16%。

## 二、链式存储：二叉链表

```c
typedef struct BiTNode {
    char data;
    struct BiTNode *lchild, *rchild;
} BiTNode, *BiTree;
```

n 个结点的二叉链表共有 2n 个链域，其中：

```text
非空链域 = 分支数 = n - 1        （除根外每个结点被一个指针指向）
空链域   = 2n - (n - 1) = n + 1
```

**空链域恰好 n+1 个**，这个结论是线索二叉树的出发点，也是常考证明题。

## 三、三叉链表

为方便找双亲，再增加一个 parent 域：

```c
typedef struct TriTNode {
    char data;
    struct TriTNode *lchild, *rchild, *parent;
} TriTNode, *TriTree;
```

3n 个链域中空链域为 2n + 1。求双亲从 O(h) 降为 O(1)，代价是每结点多一个指针。

## 四、两种存储的对比

| 维度 | 顺序存储 | 二叉链表 |
| --- | --- | --- |
| 空间 | 完全二叉树紧凑，一般树浪费大 | 每结点固定两个指针，稀疏树也够用 |
| 求双亲 | O(1)，编号 floor(i/2) | 需三叉链表或自顶向下遍历 |
| 求孩子 | O(1)，编号 2i / 2i+1 | O(1)，直接指针 |
| 插入删除 | 需搬移大量元素 | 只改指针 |
| 适用 | 满/完全二叉树、堆、优先队列 | 一般二叉树、二叉排序树、哈夫曼树 |

## 五、建树的标准输入形式

先序扩展序列（用 '#' 表示空子树）可**唯一确定**一棵二叉树，递归建树是教材的标准写法：

```c
void CreateBiTree(BiTree *T, const char *s, int *k) {
    if (s[*k] == '#') { (*k)++; *T = NULL; return; }
    *T = (BiTNode *)malloc(sizeof(BiTNode));
    (*T)->data = s[*k];
    (*k)++;
    CreateBiTree(&(*T)->lchild, s, k);
    CreateBiTree(&(*T)->rchild, s, k);
}
```

注意必须传 `BiTree *`（二级指针）才能修改调用者的头指针；序列中的 '#' 与递归调用次序一一对应，多一个少一个都会建出错树。

examples.code:
#include <stdio.h>
#include <stdlib.h>

typedef struct BiTNode {
    char data;
    struct BiTNode *lchild, *rchild;
} BiTNode, *BiTree;

static void CreateBiTree(BiTree *T, const char *s, int *k) {
    if (s[*k] == '#') { (*k)++; *T = NULL; return; }
    *T = (BiTNode *)malloc(sizeof(BiTNode));
    if (*T == NULL) { *T = NULL; printf("malloc failed\n"); return; }
    (*T)->data = s[*k];
    (*k)++;
    (*T)->lchild = NULL;
    (*T)->rchild = NULL;
    CreateBiTree(&(*T)->lchild, s, k);
    CreateBiTree(&(*T)->rchild, s, k);
}

/* nulls 统计空指针个数，即空链域数 */
static void Stat(const BiTree T, int *nodes, int *leaves, int *nulls) {
    if (T == NULL) { (*nulls)++; return; }
    (*nodes)++;
    if (T->lchild == NULL && T->rchild == NULL) { (*leaves)++; }
    Stat(T->lchild, nodes, leaves, nulls);
    Stat(T->rchild, nodes, leaves, nulls);
}

static void Destroy(BiTree T) {
    if (T == NULL) { return; }
    Destroy(T->lchild);
    Destroy(T->rchild);
    free(T);
}

int main(void) {
    const char *pre = "ABDH##I##EJ###CF##G##";
    BiTree T = NULL;
    int k = 0, nodes = 0, leaves = 0, nulls = 0;

    CreateBiTree(&T, pre, &k);
    Stat(T, &nodes, &leaves, &nulls);

    printf("先序扩展序列：%s\n", pre);
    printf("结点数 n = %d，叶子数 = %d\n", nodes, leaves);
    printf("链域总数 = 2n = %d\n", 2 * nodes);
    printf("实测空链域 = %d，公式 n+1 = %d，%s\n",
           nulls, nodes + 1, (nulls == nodes + 1) ? "吻合" : "不吻合");

    Destroy(T);
    return 0;
}

#include <stdio.h>

#define DEPTH 5

int main(void) {
    int slots = 1, k, idx;

    for (k = 1; k < DEPTH; k++) { slots = slots * 2 + 1; }

    printf("深度 k = %d\n", DEPTH);
    printf("满二叉树结点数 = 2 的 %d 次方减 1 = %d\n", DEPTH, slots);
    printf("顺序存储需分配 %d 个单元\n\n", slots);

    printf("满二叉树：结点 %2d 个，占用 %2d 单元，利用率 %d 百分比\n", slots, slots, 100);
    printf("右单支树：结点 %2d 个，占用 %2d 单元，利用率 %d 百分比\n",
           DEPTH, slots, 100 * DEPTH / slots);

    printf("\n右单支树各结点在数组中的编号（i 变 2i+1）：");
    idx = 1;
    for (k = 1; k <= DEPTH; k++) { printf("%d ", idx); idx = 2 * idx + 1; }
    printf("\n左单支树各结点在数组中的编号（i 变 2i）  ：");
    idx = 1;
    for (k = 1; k <= DEPTH; k++) { printf("%d ", idx); idx = 2 * idx; }
    printf("\n");
    return 0;
}

