## 一、四种遍历次序

| 次序 | 访问顺序 | 递归核心 | 典型用途 |
|---|---|---|---|
| 先序 DLR | 根 → 左 → 右 | ```c
visit(T); Pre(T->lchild); Pre(T->rchild);
``` | 复制树、求树深、带 `#` 标记建树 |
| 中序 LDR | 左 → 根 → 右 | ```c
In(T->lchild); visit(T); In(T->rchild);
``` | 二叉排序树得到递增序列 |
| 后序 LRD | 左 → 右 → 根 | ```c
Post(T->lchild); Post(T->rchild); visit(T);
``` | 销毁树、求表达式值（先算子树） |
| 层次 | 自上而下、自左而右 | 队列 BFS | 完全二叉树编号、按层处理 |

三种深度优先遍历的时间复杂度都是 O(n)；递归深度最坏为 n（单支树），可能栈溢出。

## 二、非递归中序（显式栈）

```c
void InOrderByStack(BiTree T)
{
    BiTree stack[64];
    int top = -1;
    BiTree p = T;
    while (p != NULL || top >= 0) {
        while (p != NULL) {        /* 一路向左入栈 */
            stack[++top] = p;
            p = p->lchild;
        }
        p = stack[top--];          /* 退栈即当前最左未访问结点 */
        printf("%c ", p->data);
        p = p->rchild;             /* 转向右子树 */
    }
}
```

层次遍历用队列：根入队，每次出队一个、访问、把其左右孩子入队，直到队空。

## 三、由遍历序列重建二叉树

- 「先序 + 中序」可重建：先序首字符是根，在中序中定位根，左侧为左子树中序、右侧为右子树中序，再按长度切分先序，递归即可。
- 「后序 + 中序」可重建：后序末字符是根，其余同理。
- 「层次 + 中序」可重建。
- 「先序 + 后序」**不可**重建：两者都只能确定根，无法区分「只有左孩子」与「只有右孩子」。

## 四、线索二叉树

n 个结点的二叉链表共有 2n 个指针域，其中 n-1 个用于指向孩子，剩余 **n+1** 个空指针。线索化就是把这些空指针改存遍历序列中的前驱/后继。

```c
typedef struct BiTNode {
    char data;
    struct BiTNode *lchild, *rchild;
    int ltag, rtag;   /* tag=0 指向孩子；tag=1 指向线索 */
} BiTNode, *BiTree;

static BiTNode *pre;  /* 全局前驱，线索化前必须置 NULL */

void InThreading(BiTree p)
{
    if (p == NULL) return;
    InThreading(p->lchild);                 /* 递归左子树 */
    if (p->lchild == NULL) {                /* 左空 → 前驱线索 */
        p->ltag = 1;
        p->lchild = pre;
    }
    if (pre != NULL && pre->rchild == NULL) { /* 前驱右空 → 后继线索 */
        pre->rtag = 1;
        pre->rchild = p;
    }
    pre = p;
    InThreading(p->rchild);                 /* 递归右子树 */
}
```

线索树上找中序后继：若 `rtag==1`，右指针即后继；否则后继是**右子树中最左下**的结点。

## 五、树、森林与二叉树的转换

- 转换法则：**左孩子右兄弟**——结点的第一个孩子作二叉树的左孩子，其余兄弟依次作右孩子链。
- 树的**先根遍历** ↔ 对应二叉树的**先序遍历**。
- 树的**后根遍历** ↔ 对应二叉树的**中序遍历**（注意不是后序）。
- 森林的先序/中序遍历同样对应二叉树的先序/中序遍历。

examples.code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct BiTNode {
    char data;
    struct BiTNode *lchild, *rchild;
} BiTNode, *BiTree;

/* 按带空子树标记 `#` 的先序串建二叉树，i 为扫描位置 */
static void CreateBiTree(BiTree *T, const char *s, size_t *i)
{
    if (s[*i] == '#') { (*i)++; *T = NULL; return; }
    *T = (BiTree)malloc(sizeof(BiTNode));
    if (*T == NULL) { perror("malloc"); exit(1); }
    (*T)->data = s[*i];
    (*i)++;
    CreateBiTree(&((*T)->lchild), s, i);
    CreateBiTree(&((*T)->rchild), s, i);
}

static void PreOrder(BiTree T)
{
    if (T == NULL) return;
    printf("%c ", T->data);
    PreOrder(T->lchild);
    PreOrder(T->rchild);
}

static void InOrder(BiTree T)
{
    if (T == NULL) return;
    InOrder(T->lchild);
    printf("%c ", T->data);
    InOrder(T->rchild);
}

static void PostOrder(BiTree T)
{
    if (T == NULL) return;
    PostOrder(T->lchild);
    PostOrder(T->rchild);
    printf("%c ", T->data);
}

/* 层次遍历：用数组模拟队列 */
static void LevelOrder(BiTree T)
{
    BiTree q[64];
    int front = 0, rear = 0;
    if (T == NULL) return;
    q[rear++] = T;
    while (front < rear) {
        BiTree p = q[front++];
        printf("%c ", p->data);
        if (p->lchild != NULL) q[rear++] = p->lchild;
        if (p->rchild != NULL) q[rear++] = p->rchild;
    }
}

static void FreeBiTree(BiTree T)
{
    if (T == NULL) return;
    FreeBiTree(T->lchild);
    FreeBiTree(T->rchild);
    free(T);
}

/* 由先序 pre 与中序 in 重建，把后序序列写入 out */
static void Rebuild(const char *pre, const char *in, char *out, size_t *k)
{
    size_t n = strlen(pre), i = 0;
    char lp[32], li[32], rp[32], ri[32];
    if (n == 0) return;
    while (in[i] != pre[0]) i++;            /* 在中序中定位根 */
    memcpy(lp, pre + 1, i);       lp[i] = '\0';
    memcpy(li, in, i);            li[i] = '\0';
    memcpy(rp, pre + 1 + i, n - 1 - i); rp[n - 1 - i] = '\0';
    memcpy(ri, in + i + 1, n - 1 - i);  ri[n - 1 - i] = '\0';
    Rebuild(lp, li, out, k);                /* 左子树 */
    Rebuild(rp, ri, out, k);                /* 右子树 */
    out[(*k)++] = pre[0];                   /* 根最后输出 → 后序 */
}

int main(void)
{
    BiTree T = NULL;
    size_t i = 0, k = 0;
    char post[32];

    CreateBiTree(&T, "ABD##E##CF##G##", &i);

    printf("先序: "); PreOrder(T);   printf("\n");
    printf("中序: "); InOrder(T);    printf("\n");
    printf("后序: "); PostOrder(T);  printf("\n");
    printf("层次: "); LevelOrder(T); printf("\n");

    Rebuild("ABDECFG", "DBEAFCG", post, &k);
    post[k] = '\0';
    printf("由先序+中序重建得到的后序: %s\n", post);

    FreeBiTree(T);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct BiTNode {
    char data;
    struct BiTNode *lchild, *rchild;
    int ltag, rtag;              /* 0 = 孩子指针；1 = 线索 */
} BiTNode, *BiTree;

static BiTree NewNode(char c)
{
    BiTree p = (BiTree)malloc(sizeof(BiTNode));
    if (p == NULL) { perror("malloc"); exit(1); }
    p->data = c;
    p->lchild = p->rchild = NULL;
    p->ltag = p->rtag = 0;
    return p;
}

static BiTree BuildDemo(void)    /* A(B(D,E), C(F,G)) */
{
    BiTree a = NewNode('A'), b = NewNode('B'), c = NewNode('C');
    BiTree d = NewNode('D'), e = NewNode('E');
    BiTree f = NewNode('F'), g = NewNode('G');
    a->lchild = b; a->rchild = c;
    b->lchild = d; b->rchild = e;
    c->lchild = f; c->rchild = g;
    return a;
}

static void InOrderByStack(BiTree T)
{
    BiTree stack[64];
    int top = -1;
    BiTree p = T;
    while (p != NULL || top >= 0) {
        while (p != NULL) { stack[++top] = p; p = p->lchild; }
        p = stack[top--];
        printf("%c ", p->data);
        p = p->rchild;
    }
}

static BiTNode *pre;             /* 中序前驱，线索化前置 NULL */

static void InThreading(BiTree p)
{
    if (p == NULL) return;
    InThreading(p->lchild);
    if (p->lchild == NULL) { p->ltag = 1; p->lchild = pre; }
    if (pre != NULL && pre->rchild == NULL) {
        pre->rtag = 1;
        pre->rchild = p;
    }
    pre = p;
    InThreading(p->rchild);
}

static void InOrderThr(BiTree T) /* 免递归免栈的中序遍历 */
{
    BiTree p = T;
    while (p != NULL) {
        while (p->ltag == 0) p = p->lchild;      /* 找最左下结点 */
        printf("%c ", p->data);
        while (p->rtag == 1 && p->rchild != NULL) {
            p = p->rchild;                       /* 沿后继线索走 */
            printf("%c ", p->data);
        }
        p = p->rchild;                           /* 进入右子树 */
    }
}

static void FreeThr(BiTree T)    /* tag==1 的指针不可再递归 */
{
    if (T == NULL) return;
    if (T->ltag == 0) FreeThr(T->lchild);
    if (T->rtag == 0) FreeThr(T->rchild);
    free(T);
}

int main(void)
{
    BiTree T = BuildDemo();

    printf("非递归中序: ");
    InOrderByStack(T);
    printf("\n");

    pre = NULL;
    InThreading(T);
    printf("线索中序  : ");
    InOrderThr(T);
    printf("\n");

    FreeThr(T);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct {
    unsigned int weight;
    unsigned int parent, lchild, rchild;
} HTNode, *HuffmanTree;

/* 在 HT[1..end] 中选 parent==0 且权值最小的两个结点 */
static void Select(HuffmanTree HT, int end, int *s1, int *s2)
{
    int i, min1 = -1, min2 = -1;
    for (i = 1; i <= end; i++) {
        if (HT[i].parent != 0) continue;
        if (min1 == -1 || HT[i].weight < HT[min1].weight) {
            min2 = min1;
            min1 = i;
        } else if (min2 == -1 || HT[i].weight < HT[min2].weight) {
            min2 = i;
        }
    }
    *s1 = min1;
    *s2 = min2;
}

static void HuffmanBuild(HuffmanTree HT, const unsigned int *w, int n)
{
    int m = 2 * n - 1, i, s1, s2;
    for (i = 1; i <= m; i++) {
        HT[i].weight = (i <= n) ? w[i - 1] : 0u;
        HT[i].parent = HT[i].lchild = HT[i].rchild = 0;
    }
    for (i = n + 1; i <= m; i++) {
        Select(HT, i - 1, &s1, &s2);
        HT[s1].parent = (unsigned int)i;
        HT[s2].parent = (unsigned int)i;
        HT[i].lchild = (unsigned int)s1;
        HT[i].rchild = (unsigned int)s2;
        HT[i].weight = HT[s1].weight + HT[s2].weight;
    }
}

/* 方法一：按定义，对叶子求 Σ(w × 深度) */
static unsigned int WPL_ByLeaf(HuffmanTree HT, int n)
{
    unsigned int sum = 0;
    int i, len, p;
    for (i = 1; i <= n; i++) {
        len = 0;
        for (p = (int)HT[i].parent; p != 0; p = (int)HT[p].parent) len++;
        sum += HT[i].weight * (unsigned int)len;
    }
    return sum;
}

/* 方法二：WPL = 所有内部结点的权值之和 */
static unsigned int WPL_ByInternal(HuffmanTree HT, int n)
{
    unsigned int sum = 0;
    int i;
    for (i = n + 1; i <= 2 * n - 1; i++) sum += HT[i].weight;
    return sum;
}

int main(void)
{
    const unsigned int w[8] = { 5, 29, 7, 8, 14, 23, 3, 11 };
    int n = 8, i;
    HuffmanTree HT = (HuffmanTree)malloc((size_t)(2 * n) * sizeof(HTNode));
    if (HT == NULL) { perror("malloc"); return 1; }

    HuffmanBuild(HT, w, n);

    printf("合并过程:\n");
    for (i = n + 1; i <= 2 * n - 1; i++)
        printf("  结点%2d = %2u + %2u = %3u\n", i,
               HT[HT[i].lchild].weight, HT[HT[i].rchild].weight, HT[i].weight);

    printf("按叶子求 WPL       = %u\n", WPL_ByLeaf(HT, n));
    printf("按内部结点求 WPL   = %u\n", WPL_ByInternal(HT, n));

    free(HT);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct {
    unsigned int weight;
    unsigned int parent, lchild, rchild;
} HTNode, *HuffmanTree;

static void Select(HuffmanTree HT, int end, int *s1, int *s2)
{
    int i, min1 = -1, min2 = -1;
    for (i = 1; i <= end; i++) {
        if (HT[i].parent != 0) continue;
        if (min1 == -1 || HT[i].weight < HT[min1].weight) {
            min2 = min1;
            min1 = i;
        } else if (min2 == -1 || HT[i].weight < HT[min2].weight) {
            min2 = i;
        }
    }
    *s1 = min1;
    *s2 = min2;
}

static void HuffmanCoding(HuffmanTree HT, int n)
{
    char *cd = (char *)malloc((size_t)n * sizeof(char));
    int i, start, p;
    unsigned int total = 0, sumw = 0;

    if (cd == NULL) { perror("malloc"); exit(1); }
    cd[n - 1] = '\0';

    for (i = 1; i <= n; i++) {
        start = n - 1;
        /* 从叶子向上回溯：是父亲的左孩子记 0，右孩子记 1 */
        for (p = (int)HT[i].parent; p != 0; p = (int)HT[p].parent)
            cd[--start] = (HT[p].lchild == (unsigned int)i) ? '0' : '1';
        printf("  权值 %2u -> 编码 %s (码长 %d)\n",
               HT[i].weight, &cd[start], n - 1 - start);
        total += HT[i].weight * (unsigned int)(n - 1 - start);
        sumw  += HT[i].weight;
    }

    printf("哈夫曼编码总位数     = %u\n", total);
    printf("等长编码(3 bit)总位数 = %u\n", 3u * sumw);
    printf("平均码长             = %.2f 位/字符\n",
           (double)total / (double)sumw);
    free(cd);
}

int main(void)
{
    const unsigned int w[8] = { 5, 29, 7, 8, 14, 23, 3, 11 };
    int n = 8, m = 2 * n - 1, i, s1, s2;
    HuffmanTree HT = (HuffmanTree)malloc(((size_t)m + 1) * sizeof(HTNode));
    if (HT == NULL) { perror("malloc"); return 1; }

    for (i = 1; i <= m; i++) {
        HT[i].weight = (i <= n) ? w[i - 1] : 0u;
        HT[i].parent = HT[i].lchild = HT[i].rchild = 0;
    }
    for (i = n + 1; i <= m; i++) {
        Select(HT, i - 1, &s1, &s2);
        HT[s1].parent = (unsigned int)i;
        HT[s2].parent = (unsigned int)i;
        HT[i].lchild  = (unsigned int)s1;
        HT[i].rchild  = (unsigned int)s2;
        HT[i].weight  = HT[s1].weight + HT[s2].weight;
    }

    HuffmanCoding(HT, n);

    free(HT);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* 普通树的孩子兄弟表示：firstChild 指向第一个孩子，nextSibling 指向下一个兄弟 */
typedef struct CSNode {
    char data;
    struct CSNode *firstChild, *nextSibling;
} CSNode, *CSTree;

static CSTree mk(char d, CSTree firstChild, CSTree nextSibling)
{
    CSTree p = (CSTree)malloc(sizeof(CSNode));

    if (p == NULL) {
        return NULL;
    }
    p->data = d;
    p->firstChild = firstChild;
    p->nextSibling = nextSibling;
    return p;
}

/* 缩进打印：同层缩进相同的互为兄弟 */
static void dump(CSTree t, int level)
{
    CSTree p;

    if (t == NULL) {
        return;
    }
    for (p = t; p != NULL; p = p->nextSibling) {
        int i;

        for (i = 0; i < level; i++) {
            printf("  ");
        }
        printf("%c\n", p->data);
        dump(p->firstChild, level + 1);
    }
}

static int countNodes(CSTree t)
{
    CSTree p;
    int n;

    if (t == NULL) {
        return 0;
    }
    n = 1;
    for (p = t->firstChild; p != NULL; p = p->nextSibling) {
        n += countNodes(p);
    }
    return n;
}

static int countLeaves(CSTree t)
{
    CSTree p;
    int n = 0;

    if (t == NULL) {
        return 0;
    }
    if (t->firstChild == NULL) {
        return 1;
    }
    for (p = t->firstChild; p != NULL; p = p->nextSibling) {
        n += countLeaves(p);
    }
    return n;
}

/* 所有结点的度数之和 = 边数 */
static int sumDegree(CSTree t)
{
    CSTree p;
    int childCount = 0, s;

    if (t == NULL) {
        return 0;
    }
    for (p = t->firstChild; p != NULL; p = p->nextSibling) {
        childCount++;
    }
    s = childCount;
    for (p = t->firstChild; p != NULL; p = p->nextSibling) {
        s += sumDegree(p);
    }
    return s;
}

/* 树的度 = 所有结点度数的最大值 */
static int treeDegree(CSTree t)
{
    CSTree p;
    int childCount = 0, maxChild = 0, d;

    if (t == NULL) {
        return 0;
    }
    for (p = t->firstChild; p != NULL; p = p->nextSibling) {
        childCount++;
    }
    for (p = t->firstChild; p != NULL; p = p->nextSibling) {
        d = treeDegree(p);
        if (d > maxChild) {
            maxChild = d;
        }
    }
    return (childCount > maxChild) ? childCount : maxChild;
}

static int treeDepth(CSTree t)
{
    CSTree p;
    int maxD = 0, d;

    if (t == NULL) {
        return 0;
    }
    for (p = t->firstChild; p != NULL; p = p->nextSibling) {
        d = treeDepth(p);
        if (d > maxD) {
            maxD = d;
        }
    }
    return maxD + 1;
}

static int levelCount(CSTree t, int cur, int want)
{
    CSTree p;
    int n = 0;

    if (t == NULL) {
        return 0;
    }
    if (cur == want) {
        return 1;
    }
    for (p = t->firstChild; p != NULL; p = p->nextSibling) {
        n += levelCount(p, cur + 1, want);
    }
    return n;
}

/* 找根到 target 的路径，返回路径长度；path[0] 是根 */
static int findPath(CSTree t, char target, char *path)
{
    CSTree p;
    int len;

    if (t == NULL) {
        return 0;
    }
    path[0] = t->data;
    if (t->data == target) {
        return 1;
    }
    for (p = t->firstChild; p != NULL; p = p->nextSibling) {
        len = findPath(p, target, path + 1);
        if (len > 0) {
            return len + 1;
        }
    }
    return 0;
}

static int countChildrenOf(CSTree t, char who)
{
    CSTree p;
    int n = 0;

    if (t == NULL) {
        return 0;
    }
    if (t->data == who) {
        for (p = t->firstChild; p != NULL; p = p->nextSibling) {
            n++;
        }
        return n;
    }
    for (p = t->firstChild; p != NULL; p = p->nextSibling) {
        n = countChildrenOf(p, who);
        if (n > 0) {
            return n;
        }
    }
    return 0;
}

static void destroyCS(CSTree t)
{
    CSTree p, next;

    for (p = t; p != NULL; p = next) {
        next = p->nextSibling;
        destroyCS(p->firstChild);
        free(p);
    }
}

int main(void)
{
    /*        A
       /  |  \
      B   C   D
     / \      |
    E   F     G                                              */
    CSTree E = mk('E', NULL, mk('F', NULL, NULL));
    CSTree D = mk('D', mk('G', NULL, NULL), NULL);
    CSTree C = mk('C', NULL, D);
    CSTree B = mk('B', E, C);
    CSTree T = mk('A', B, NULL);
    char path[16];
    int plen, nodes, sum, lv, i;

    printf("树 T 的缩进表示（同缩进为兄弟）：\n");
    dump(T, 0);

    nodes = countNodes(T);
    sum = sumDegree(T);
    printf("\n结点总数 = %d\n", nodes);
    printf("叶子结点数 = %d\n", countLeaves(T));
    printf("树的度 = %d（各结点度数的最大值）\n", treeDegree(T));
    printf("所有结点的度数之和 = %d\n", sum);
    printf("结点数 - 1 = %d  → 恒等式「度数和 == 结点数-1」成立 = %d\n",
           nodes - 1, sum == nodes - 1);
    printf("树的深度 = %d\n", treeDepth(T));
    for (lv = 1; lv <= treeDepth(T); lv++) {
        printf("第 %d 层结点数 = %d\n", lv, levelCount(T, 1, lv));
    }

    printf("\n术语实例：\n");
    plen = findPath(T, 'G', path);
    printf("  G 的双亲 = %c，G 的祖先（自下而上）=", path[plen - 2]);
    for (i = plen - 2; i >= 0; i--) {
        printf("%c ", path[i]);
    }
    printf("共 %d 个\n", plen - 1);

    plen = findPath(T, 'E', path);
    printf("  E 的双亲 = %c\n", path[plen - 2]);
    printf("  E 的兄弟数（含自己）= %d → 兄弟是 F\n", countChildrenOf(T, 'E' == path[0] ? 'E' : path[plen - 2]));
    printf("  E 的堂兄弟数 = 同层结点数 %d - 兄弟数 %d = %d\n",
           levelCount(T, 1, plen), countChildrenOf(T, path[plen - 2]),
           levelCount(T, 1, plen) - countChildrenOf(T, path[plen - 2]));
    printf("  A 的子孙数 = 结点总数 %d - 1（不含自己）= %d\n", nodes, nodes - 1);

    destroyCS(T);
    printf("\n树已释放\n");
    return 0;
}

#include <stdio.h>

#define CAP 16          /* 下标 1..CAP-1 可用，0 号不用 */

/* 打印层次编号内容，0 表示该编号无结点 */
static void showLevelOrder(const char *name, const int *a, int cap)
{
    int i;

    printf("%s\n  层次编号内容 =", name);
    for (i = 1; i <= cap; i++) {
        printf(" %d", a[i]);
    }
    printf("\n");
}

/* 统计有效结点数与最大编号 */
static int countNodesArr(const int *a, int cap)
{
    int i, n = 0;

    for (i = 1; i <= cap; i++) {
        if (a[i] != 0) {
            n++;
        }
    }
    return n;
}

static int maxIndexArr(const int *a, int cap)
{
    int i, m = 0;

    for (i = 1; i <= cap; i++) {
        if (a[i] != 0) {
            m = i;
        }
    }
    return m;
}

/* 完全二叉树 ⟺ 编号 1..maxIdx 之间没有空洞；*hole 返回第一个空洞编号（0 表示无） */
static int isCompleteArr(const int *a, int cap, int *hole)
{
    int m = maxIndexArr(a, cap), i;

    *hole = 0;
    for (i = 1; i <= m; i++) {
        if (a[i] == 0) {
            *hole = i;
            return 0;
        }
    }
    return 1;
}

/* 整数求 floor(log2(x)) + 1，不用 math.h，避免浮点误差 */
static int heightOf(int maxIdx)
{
    int h = 0, v = maxIdx;

    while (v > 0) {
        h++;
        v /= 2;
    }
    return h;
}

/* 2 的整数幂 */
static int pow2(int e)
{
    int r = 1, i;

    for (i = 0; i < e; i++) {
        r *= 2;
    }
    return r;
}

static int isFullArr(const int *a, int cap)
{
    int hole, n, h;

    if (!isCompleteArr(a, cap, &hole)) {
        return 0;
    }
    n = countNodesArr(a, cap);
    h = heightOf(maxIndexArr(a, cap));
    return n == pow2(h) - 1;
}

static void reportNeighbors(const int *a, int cap, int n)
{
    int i, p, l, r;

    printf("\n编号 i 的邻居关系（顺序存储的核心公式）:\n");
    for (i = 1; i <= cap; i++) {
        if (a[i] == 0) {
            continue;
        }
        p = i / 2;
        l = 2 * i;
        r = 2 * i + 1;
        printf("  i=%d: 双亲=%s", i, (i == 1) ? "无(根)" : "");
        if (i != 1) {
            printf("%d", p);
        }
        printf("  左孩子=");
        if (l > n) {
            printf("%d(越界,无)", l);
        } else {
            printf("%d", l);
        }
        printf("  右孩子=");
        if (r > n) {
            printf("%d(越界,无)", r);
        } else {
            printf("%d", r);
        }
        printf("\n");
    }
}

int main(void)
{
    /* 用例1：满二叉树，7 个结点，高度 3 */
    int t1[CAP] = { 0, 1, 2, 3, 4, 5, 6, 7 };
    /* 用例2：完全二叉树但不满，6 个结点（缺编号 7） */
    int t2[CAP] = { 0, 1, 2, 3, 4, 5, 6, 0 };
    /* 用例3：不是完全二叉树，缺编号 6 却有编号 7 */
    int t3[CAP] = { 0, 1, 2, 3, 4, 5, 0, 7 };
    int cap1 = 7, cap2 = 7, cap3 = 7;
    int hole = 0, n, h;

    showLevelOrder("用例1: 满二叉树（7 个结点）", t1, cap1);
    n = countNodesArr(t1, cap1);
    h = heightOf(maxIndexArr(t1, cap1));
    printf("  结点数 = %d  最大编号 = %d  高度 = %d\n", n, maxIndexArr(t1, cap1), h);
    printf("  是否完全二叉树 = %d\n", isCompleteArr(t1, cap1, &hole));
    printf("  是否满二叉树 = %d（结点数 %d == 2^%d-1 = %d）\n",
           isFullArr(t1, cap1), n, h, pow2(h) - 1);
    reportNeighbors(t1, cap1, n);

    printf("\n");
    showLevelOrder("用例2: 完全二叉树但不满（6 个结点）", t2, cap2);
    n = countNodesArr(t2, cap2);
    h = heightOf(maxIndexArr(t2, cap2));
    printf("  结点数 = %d  最大编号 = %d  高度 = %d\n", n, maxIndexArr(t2, cap2), h);
    printf("  是否完全二叉树 = %d\n", isCompleteArr(t2, cap2, &hole));
    printf("  是否满二叉树 = %d（结点数 %d != 2^%d-1 = %d）\n",
           isFullArr(t2, cap2), n, h, pow2(h) - 1);
    reportNeighbors(t2, cap2, n);

    printf("\n");
    showLevelOrder("用例3: 不是完全二叉树（缺编号 6 却有编号 7）", t3, cap3);
    n = countNodesArr(t3, cap3);
    h = heightOf(maxIndexArr(t3, cap3));
    printf("  结点数 = %d  最大编号 = %d  高度 = %d\n", n, maxIndexArr(t3, cap3), h);
    printf("  是否完全二叉树 = %d", isCompleteArr(t3, cap3, &hole));
    if (hole != 0) {
        printf("（编号 %d 空缺，但更大的编号 %d 有结点 → 有空洞）", hole, maxIndexArr(t3, cap3));
    }
    printf("\n");
    printf("  是否满二叉树 = %d\n", isFullArr(t3, cap3));
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct BiTNode {
    char data;
    struct BiTNode *lchild, *rchild;
} BiTNode, *BiTree;

/* 按先序串建树，'#' 表示空子树；*i 是游标 */
static void createBiTree(BiTree *T, const char *pre, int *i)
{
    char ch;

    ch = pre[(*i)++];
    if (ch == '#' || ch == '\0') {
        *T = NULL;
        return;
    }
    *T = (BiTNode *)malloc(sizeof(BiTNode));
    if (*T == NULL) {
        return;
    }
    (*T)->data = ch;
    createBiTree(&(*T)->lchild, pre, i);
    createBiTree(&(*T)->rchild, pre, i);
}

static int nodeCount(BiTree t)
{
    if (t == NULL) {
        return 0;
    }
    return 1 + nodeCount(t->lchild) + nodeCount(t->rchild);
}

/* 分别统计度为 0/1/2 的结点数 */
static void countByDegree(BiTree t, int *n0, int *n1, int *n2)
{
    int d;

    if (t == NULL) {
        return;
    }
    d = (t->lchild != NULL) + (t->rchild != NULL);
    if (d == 0) {
        (*n0)++;
    } else if (d == 1) {
        (*n1)++;
    } else {
        (*n2)++;
    }
    countByDegree(t->lchild, n0, n1, n2);
    countByDegree(t->rchild, n0, n1, n2);
}

static int height(BiTree t)
{
    int hl, hr;

    if (t == NULL) {
        return 0;
    }
    hl = height(t->lchild);
    hr = height(t->rchild);
    return (hl > hr ? hl : hr) + 1;
}

static int levelCount(BiTree t, int cur, int want)
{
    if (t == NULL) {
        return 0;
    }
    if (cur == want) {
        return 1;
    }
    return levelCount(t->lchild, cur + 1, want) + levelCount(t->rchild, cur + 1, want);
}

/* 完全二叉树判别：先序建树后按层次编号检查空洞，这里用「编号法」等价实现 */
static int isComplete(BiTree t)
{
    BiTNode *queue[64];
    int front = 0, rear = 0, sawNull = 0;
    BiTNode *p;

    if (t == NULL) {
        return 1;
    }
    queue[rear++] = t;
    while (front < rear) {
        p = queue[front++];
        if (p == NULL) {
            sawNull = 1;               /* 第一次遇到空位 */
            continue;
        }
        if (sawNull) {
            return 0;                  /* 空位之后又出现结点 → 有空洞 */
        }
        queue[rear++] = p->lchild;
        queue[rear++] = p->rchild;
    }
    return 1;
}

static int floorLog2(int n)
{
    int h = 0;

    while (n > 0) {
        h++;
        n /= 2;
    }
    return h - 1;                      /* floor(log2 n) */
}

static int pow2(int e)
{
    int r = 1, i;

    for (i = 0; i < e; i++) {
        r *= 2;
    }
    return r;
}

static void destroyTree(BiTree t)
{
    if (t == NULL) {
        return;
    }
    destroyTree(t->lchild);
    destroyTree(t->rchild);
    free(t);
}

static void checkOne(const char *pre)
{
    BiTree t = NULL;
    int i = 0, n0 = 0, n1 = 0, n2 = 0, n, h, lv, ok12 = 1;

    createBiTree(&t, pre, &i);
    n = nodeCount(t);
    h = height(t);
    countByDegree(t, &n0, &n1, &n2);

    printf("先序串 %s → 结点数=%d 高度=%d n0=%d n1=%d n2=%d", pre, n, h, n0, n1, n2);
    printf("  | n2+1=%d %s n0=%d", n2 + 1, (n2 + 1 == n0) ? "==" : "!=", n0);
    printf("  性质3成立=%d\n", n2 + 1 == n0);

    if (n > 0) {
        for (lv = 1; lv <= h; lv++) {
            if (levelCount(t, 1, lv) > pow2(lv - 1)) {
                ok12 = 0;
            }
        }
        printf("    性质1（第 i 层 ≤ 2^(i-1)）逐层检查成立=%d", ok12);
        printf("  各层结点数:");
        for (lv = 1; lv <= h; lv++) {
            printf(" %d/%d", levelCount(t, 1, lv), pow2(lv - 1));
        }
        printf("\n");
        printf("    性质2（结点 ≤ 2^h-1 = %d）成立=%d", pow2(h) - 1, n <= pow2(h) - 1);
        printf("  是满二叉树=%d\n", n == pow2(h) - 1);
        printf("    是完全二叉树=%d", isComplete(t));
        if (isComplete(t)) {
            printf("  性质4（h == floor(log2 n)+1 = %d）成立=%d",
                   floorLog2(n) + 1, h == floorLog2(n) + 1);
        } else {
            printf("  （非完全二叉树，性质4 不适用）");
        }
        printf("\n");
    }
    printf("\n");
    destroyTree(t);
}

int main(void)
{
    printf("== 性质3：n0 = n2 + 1 ==\n\n");
    checkOne("A##");
    checkOne("AB##C##");
    checkOne("ABD##E##C##");
    checkOne("AB##C#D##");
    checkOne("ABD##E##CF###");
    checkOne("ABD##E##CF##G##");
    checkOne("ABC####");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

/* ===== 二叉链表 ===== */
typedef struct BiTNode {
    char data;
    struct BiTNode *lchild, *rchild;
} BiTNode, *BiTree;

static void createBiTree(BiTree *T, const char *pre, int *i)
{
    char ch = pre[(*i)++];

    if (ch == '#' || ch == '\0') {
        *T = NULL;
        return;
    }
    *T = (BiTNode *)malloc(sizeof(BiTNode));
    if (*T == NULL) {
        return;
    }
    (*T)->data = ch;
    createBiTree(&(*T)->lchild, pre, i);
    createBiTree(&(*T)->rchild, pre, i);
}

/* 统计空链域：左空 + 右空，同时输出每个结点的明细 */
static int countNullLinks(BiTree t, int detail)
{
    int n = 0;

    if (t == NULL) {
        return 0;
    }
    if (t->lchild == NULL) {
        n++;
    }
    if (t->rchild == NULL) {
        n++;
    }
    if (detail) {
        printf("    %c: 左%s 右%s → 空链域 %d\n", t->data,
               t->lchild ? "非空" : "空  ",
               t->rchild ? "非空" : "空  ",
               (t->lchild == NULL) + (t->rchild == NULL));
    }
    n += countNullLinks(t->lchild, detail);
    n += countNullLinks(t->rchild, detail);
    return n;
}

static int nodeCount(BiTree t)
{
    if (t == NULL) {
        return 0;
    }
    return 1 + nodeCount(t->lchild) + nodeCount(t->rchild);
}

/* 在二叉链表里找 target 的双亲，*visited 记录访问过的非空结点数 */
static BiTNode *findParentBi(BiTree t, char target, int *visited)
{
    BiTNode *r;

    if (t == NULL) {
        return NULL;
    }
    (*visited)++;
    if ((t->lchild != NULL && t->lchild->data == target) ||
        (t->rchild != NULL && t->rchild->data == target)) {
        return t;
    }
    r = findParentBi(t->lchild, target, visited);
    if (r != NULL) {
        return r;
    }
    return findParentBi(t->rchild, target, visited);
}

static void destroyBi(BiTree t)
{
    if (t == NULL) {
        return;
    }
    destroyBi(t->lchild);
    destroyBi(t->rchild);
    free(t);
}

/* ===== 三叉链表 ===== */
typedef struct TriTNode {
    char data;
    struct TriTNode *parent, *lchild, *rchild;
} TriTNode, *TriTree;

/* 建三叉链表：复用二叉链表的形状，建完一趟回填 parent */
static void createTri(TriTree *T, TriTree par, const char *pre, int *i)
{
    char ch = pre[(*i)++];

    if (ch == '#' || ch == '\0') {
        *T = NULL;
        return;
    }
    *T = (TriTNode *)malloc(sizeof(TriTNode));
    if (*T == NULL) {
        return;
    }
    (*T)->data = ch;
    (*T)->parent = par;
    createTri(&(*T)->lchild, *T, pre, i);
    createTri(&(*T)->rchild, *T, pre, i);
}

static TriTNode *findNodeTri(TriTree t, char target)
{
    TriTNode *r;

    if (t == NULL) {
        return NULL;
    }
    if (t->data == target) {
        return t;
    }
    r = findNodeTri(t->lchild, target);
    if (r != NULL) {
        return r;
    }
    return findNodeTri(t->rchild, target);
}

static int countNullLinksTri(TriTree t)
{
    int n = 0;

    if (t == NULL) {
        return 0;
    }
    if (t->parent == NULL) {
        n++;
    }
    if (t->lchild == NULL) {
        n++;
    }
    if (t->rchild == NULL) {
        n++;
    }
    n += countNullLinksTri(t->lchild);
    n += countNullLinksTri(t->rchild);
    return n;
}

static void destroyTri(TriTree t)
{
    if (t == NULL) {
        return;
    }
    destroyTri(t->lchild);
    destroyTri(t->rchild);
    free(t);
}

int main(void)
{
    const char *pres[3];
    int k;

    pres[0] = "ABD##E##C#F##";
    pres[1] = "AB##C##";
    pres[2] = "ABC####";

    printf("== 二叉链表：空链域实测 vs 公式 n+1 ==\n");
    for (k = 0; k < 3; k++) {
        BiTree t = NULL;
        int i = 0, n, nulls;

        createBiTree(&t, pres[k], &i);
        n = nodeCount(t);
        printf("  先序串 %s: n=%d  指针域总数 2n=%d  已用(边数)n-1=%d\n",
               pres[k], n, 2 * n, n - 1);
        nulls = countNullLinks(t, 0);
        printf("    空链域实测 = %d  公式 n+1 = %d  相符 = %d\n", nulls, n + 1, nulls == n + 1);
        destroyBi(t);
    }

    printf("\n== 逐结点空链域明细（ABD##E##C#F##）==\n");
    {
        BiTree t = NULL;
        int i = 0;

        createBiTree(&t, "ABD##E##C#F##", &i);
        printf("    合计 = %d\n", countNullLinks(t, 1));
        destroyBi(t);
    }

    printf("\n== 找双亲的代价：二叉链表 O(n) vs 三叉链表 O(1) ==\n");
    {
        BiTree t = NULL;
        TriTree tt = NULL;
        int i = 0, visited = 0;
        BiTNode *p;
        TriTNode *tp;

        createBiTree(&t, "ABD##E##C#F##", &i);
        p = findParentBi(t, 'F', &visited);
        printf("  二叉链表找 F 的双亲：访问了 %d 个结点（全树共 %d 个），双亲 = %c\n",
               visited, nodeCount(t), p ? p->data : '?');

        i = 0;
        createTri(&tt, NULL, "ABD##E##C#F##", &i);
        tp = findNodeTri(tt, 'F');
        printf("  三叉链表找 F 的双亲：直接读 parent 域，访问结点数 = 1，双亲 = %c\n",
               tp->parent ? tp->parent->data : '?');
        printf("  代价：三叉链表每结点多用 1 个指针域，n=6 时多用 6 个\n");

        visited = 0;
        p = findParentBi(t, 'D', &visited);
        printf("  二叉链表找 D 的双亲（离根近）：访问 %d 个结点，双亲 = %c\n",
               visited, p ? p->data : '?');
        printf("  → 目标越深、越靠右，二叉链表的搜索代价越大；三叉链表恒为 1\n");

        printf("  三叉链表空链域 = %d（公式 n+2 = %d，含根的空 parent）\n",
               countNullLinksTri(tt), nodeCount(t) + 2);

        destroyBi(t);
        destroyTri(tt);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct BiTNode {
    char data;
    struct BiTNode *lchild, *rchild;
} BiTNode, *BiTree;

static void createBiTree(BiTree *T, const char *pre, int *i)
{
    char ch = pre[(*i)++];

    if (ch == '#' || ch == '\0') {
        *T = NULL;
        return;
    }
    *T = (BiTNode *)malloc(sizeof(BiTNode));
    if (*T == NULL) {
        return;
    }
    (*T)->data = ch;
    createBiTree(&(*T)->lchild, pre, i);
    createBiTree(&(*T)->rchild, pre, i);
}

/* 三种遍历：*maxStack 记录递归工作栈的最大深度，*calls 记录函数被调用的总次数 */
static void preorder(BiTree t, char *out, int *len, int depth, int *maxStack, int *calls)
{
    (*calls)++;
    if (t == NULL) {
        return;                              /* 空链域触发的调用不计入有效工作栈层 */
    }
    if (depth > *maxStack) {
        *maxStack = depth;                   /* ★ 只统计非空结点 → 最大深度恰等于树高 */
    }
    out[(*len)++] = t->data;                 /* ★ 根在最前 */
    preorder(t->lchild, out, len, depth + 1, maxStack, calls);
    preorder(t->rchild, out, len, depth + 1, maxStack, calls);
}

static void inorder(BiTree t, char *out, int *len)
{
    if (t == NULL) {
        return;
    }
    inorder(t->lchild, out, len);
    out[(*len)++] = t->data;                 /* ★ 根在中间 */
    inorder(t->rchild, out, len);
}

static void postorder(BiTree t, char *out, int *len)
{
    if (t == NULL) {
        return;
    }
    postorder(t->lchild, out, len);
    postorder(t->rchild, out, len);
    out[(*len)++] = t->data;                 /* ★ 根在最后 */
}

/* 层次遍历：队列实现 */
static void levelorder(BiTree t, char *out, int *len)
{
    BiTNode *queue[64];
    int front = 0, rear = 0;

    if (t == NULL) {
        return;
    }
    queue[rear++] = t;
    while (front < rear) {
        BiTNode *p = queue[front++];

        out[(*len)++] = p->data;
        if (p->lchild != NULL && rear < 64) {
            queue[rear++] = p->lchild;
        }
        if (p->rchild != NULL && rear < 64) {
            queue[rear++] = p->rchild;
        }
    }
}

static int nodeCount(BiTree t)
{
    if (t == NULL) {
        return 0;
    }
    return 1 + nodeCount(t->lchild) + nodeCount(t->rchild);
}

static void printSeq(const char *label, const char *seq, int len)
{
    int i;

    printf("  %s = ", label);
    if (len == 0) {
        printf("(空)");
    }
    for (i = 0; i < len; i++) {
        printf("%c ", seq[i]);
    }
    printf("\n");
}

static void destroyTree(BiTree t)
{
    if (t == NULL) {
        return;
    }
    destroyTree(t->lchild);                  /* ★ 后序释放：先孩子后自己 */
    destroyTree(t->rchild);
    free(t);
}

int main(void)
{
    const char *pres[5];
    const char *desc[5];
    int k;

    pres[0] = "ABD##E##C#F##";  desc[0] = "普通二叉树";
    pres[1] = "AB##C##";        desc[1] = "满二叉树(3结点)";
    pres[2] = "A##";            desc[2] = "只有一个根";
    pres[3] = "ABC####";        desc[3] = "左斜链(单支树)";
    pres[4] = "#";              desc[4] = "空树";

    for (k = 0; k < 5; k++) {
        BiTree t = NULL;
        char pre[64], in[64], post[64], lvl[64];
        int lp = 0, li = 0, lq = 0, ll = 0, i = 0, maxStack = 0, calls = 0;

        createBiTree(&t, pres[k], &i);
        preorder(t, pre, &lp, 1, &maxStack, &calls);
        inorder(t, in, &li);
        postorder(t, post, &lq);
        levelorder(t, lvl, &ll);

        printf("树%d [%s] 先序串 = %s  结点数 = %d\n", k + 1, desc[k], pres[k], nodeCount(t));
        printSeq("先序 DLR", pre, lp);
        printSeq("中序 LDR", in, li);
        printSeq("后序 LRD", post, lq);
        printSeq("层次    ", lvl, ll);
        printf("  递归代价：先序函数被调用 %d 次（= 2n+1 = %d），工作栈最大深度 %d\n\n",
               calls, 2 * nodeCount(t) + 1, maxStack);
        destroyTree(t);
    }
    return 0;
}

