#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXSTACK 64

typedef struct BiTNode {
    char data;
    struct BiTNode *lchild, *rchild;
} BiTNode, *BiTree;

static void createBiTree(BiTree *T, const char *pre, int *i)
{
    char ch = pre[(*i)++];

    if (ch == '#' || ch == '\0') {
        *T = NULL;
        return;
    }
    *T = (BiTNode *)malloc(sizeof(BiTNode));
    if (*T == NULL) {
        return;
    }
    (*T)->data = ch;
    createBiTree(&(*T)->lchild, pre, i);
    createBiTree(&(*T)->rchild, pre, i);
}

/* ---------- 递归版 ---------- */
static void inorderRec(BiTree t, char *out, int *len)
{
    if (t == NULL) {
        return;
    }
    inorderRec(t->lchild, out, len);
    out[(*len)++] = t->data;
    inorderRec(t->rchild, out, len);
}

static void preorderRec(BiTree t, char *out, int *len)
{
    if (t == NULL) {
        return;
    }
    out[(*len)++] = t->data;
    preorderRec(t->lchild, out, len);
    preorderRec(t->rchild, out, len);
}

static void postorderRec(BiTree t, char *out, int *len)
{
    if (t == NULL) {
        return;
    }
    postorderRec(t->lchild, out, len);
    postorderRec(t->rchild, out, len);
    out[(*len)++] = t->data;
}

/* ---------- 非递归版 ---------- */
static void inorderIter(BiTree t, char *out, int *len, int *pushes, int *maxDepth)
{
    BiTNode *stack[MAXSTACK], *p = t;
    int top = -1;

    while (p != NULL || top >= 0) {          /* ★ 双条件缺一不可 */
        while (p != NULL) {
            if (top + 1 >= MAXSTACK) {
                printf("  [栈满，截断]\n");
                return;
            }
            stack[++top] = p;
            (*pushes)++;
            if (top + 1 > *maxDepth) {
                *maxDepth = top + 1;
            }
            p = p->lchild;
        }
        if (top >= 0) {
            p = stack[top--];
            out[(*len)++] = p->data;
            p = p->rchild;
        }
    }
}

static void preorderIter(BiTree t, char *out, int *len)
{
    BiTNode *stack[MAXSTACK], *p = t;
    int top = -1;

    if (t == NULL) {
        return;
    }
    stack[++top] = t;
    while (top >= 0) {
        p = stack[top--];
        out[(*len)++] = p->data;
        if (p->rchild != NULL && top + 1 < MAXSTACK) {
            stack[++top] = p->rchild;        /* ★ 先压右 */
        }
        if (p->lchild != NULL && top + 1 < MAXSTACK) {
            stack[++top] = p->lchild;        /* ★ 后压左，LIFO 保证左先出 */
        }
    }
}

static void postorderIter(BiTree t, char *out, int *len)
{
    BiTNode *stack[MAXSTACK], *p = t, *prev = NULL;
    int top = -1;

    while (p != NULL || top >= 0) {
        while (p != NULL) {
            if (top + 1 >= MAXSTACK) {
                printf("  [栈满，截断]\n");
                return;
            }
            stack[++top] = p;
            p = p->lchild;
        }
        if (top >= 0) {
            p = stack[top];                  /* ★ 只窥视栈顶，不弹出 */
            if (p->rchild == NULL || p->rchild == prev) {
                out[(*len)++] = p->data;
                top--;
                prev = p;                    /* ★ 记住刚访问的 */
                p = NULL;                    /* ★ 置空防止再次下探 */
            } else {
                p = p->rchild;
            }
        }
    }
}

/* 后序逆序法：先做「根右左」，结果倒序即「左右根」 */
static void postorderByReverse(BiTree t, char *out, int *len)
{
    BiTNode *stack[MAXSTACK], *p = t;
    char tmp[MAXSTACK];
    int top = -1, tn = 0, i;

    if (t == NULL) {
        return;
    }
    stack[++top] = t;
    while (top >= 0) {
        p = stack[top--];
        tmp[tn++] = p->data;
        if (p->lchild != NULL && top + 1 < MAXSTACK) {
            stack[++top] = p->lchild;        /* ★ 先压左 */
        }
        if (p->rchild != NULL && top + 1 < MAXSTACK) {
            stack[++top] = p->rchild;        /* ★ 后压右 → 右先出，得「根右左」 */
        }
    }
    for (i = tn - 1; i >= 0; i--) {
        out[(*len)++] = tmp[i];              /* 倒序输出 */
    }
}

/* 只输出序列体；label 由调用方一次 printf 打完，避免多段拼接产生歧义空格 */
static void printBody(const char *seq, int len)
{
    int i;

    if (len == 0) {
        printf("(空)");
        return;
    }
    for (i = 0; i < len; i++) {
        if (i > 0) {
            printf(" ");
        }
        printf("%c", seq[i]);
    }
}

static int seqEqual(const char *a, int la, const char *b, int lb)
{
    return (la == lb) && (la == 0 || memcmp(a, b, (size_t)la) == 0);
}

static int nodeCount(BiTree t)
{
    if (t == NULL) {
        return 0;
    }
    return 1 + nodeCount(t->lchild) + nodeCount(t->rchild);
}

static void destroyTree(BiTree t)
{
    if (t == NULL) {
        return;
    }
    destroyTree(t->lchild);
    destroyTree(t->rchild);
    free(t);
}

int main(void)
{
    const char *pres[4];
    const char *desc[4];
    int k;

    pres[0] = "ABD##E##C#F##";  desc[0] = "普通二叉树";
    pres[1] = "ABC####";        desc[1] = "左斜链(单支树)";
    pres[2] = "ABD##E##CF##G##";desc[2] = "满二叉树(7结点)";
    pres[3] = "#";              desc[3] = "空树";

    for (k = 0; k < 4; k++) {
        BiTree t = NULL;
        char ir[64], ii[64], pr[64], pi[64], qr[64], qi[64], qrev[64];
        int lir = 0, lii = 0, lpr = 0, lpi = 0, lqr = 0, lqi = 0, lqrev = 0;
        int i = 0, pushes = 0, maxDepth = 0;

        createBiTree(&t, pres[k], &i);
        inorderRec(t, ir, &lir);
        inorderIter(t, ii, &lii, &pushes, &maxDepth);
        preorderRec(t, pr, &lpr);
        preorderIter(t, pi, &lpi);
        postorderRec(t, qr, &lqr);
        postorderIter(t, qi, &lqi);
        postorderByReverse(t, qrev, &lqrev);

        printf("树%d [%s] 先序串 = %s  结点数 = %d\n", k + 1, desc[k], pres[k], nodeCount(t));
        printf("  中序: 递归=");
        printBody(ir, lir);
        printf(" | 非递归=");
        printBody(ii, lii);
        printf(" | 一致=%d\n", seqEqual(ir, lir, ii, lii));
        printf("  先序: 递归=");
        printBody(pr, lpr);
        printf(" | 非递归=");
        printBody(pi, lpi);
        printf(" | 一致=%d\n", seqEqual(pr, lpr, pi, lpi));
        printf("  后序: 递归=");
        printBody(qr, lqr);
        printf(" | prev法=");
        printBody(qi, lqi);
        printf(" | 逆序法=");
        printBody(qrev, lqrev);
        printf(" | 一致=%d/%d\n",
               seqEqual(qr, lqr, qi, lqi), seqEqual(qr, lqr, qrev, lqrev));
        printf("  中序非递归统计: 入栈 %d 次（结点数 %d），最大栈深 %d\n\n",
               pushes, nodeCount(t), maxDepth);
        destroyTree(t);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MAXN 64

typedef struct BiTNode {
    char data;
    struct BiTNode *lchild, *rchild;
} BiTNode, *BiTree;

static void createBiTree(BiTree *T, const char *pre, int *i)
{
    char c = pre[*i];

    if (c == '\0' || c == '#') {
        *T = NULL;
        if (c != '\0') {
            (*i)++;
        }
        return;
    }
    (*i)++;
    *T = (BiTree)malloc(sizeof(BiTNode));
    (*T)->data = c;
    createBiTree(&(*T)->lchild, pre, i);
    createBiTree(&(*T)->rchild, pre, i);
}

static void destroyBiTree(BiTree *T)
{
    if (*T == NULL) {
        return;
    }
    destroyBiTree(&(*T)->lchild);
    destroyBiTree(&(*T)->rchild);
    free(*T);
    *T = NULL;
}

/* 基本层次遍历：out 存访问次序，返回结点数 */
static int levelOrder(BiTree t, char *out)
{
    BiTree q[MAXN];
    int front = 0, rear = 0, len = 0;

    if (t == NULL) {
        return 0;
    }
    q[rear++] = t;
    while (front < rear) {
        BiTree p = q[front++];

        out[len++] = p->data;
        if (p->lchild != NULL) {
            q[rear++] = p->lchild;
        }
        if (p->rchild != NULL) {
            q[rear++] = p->rchild;
        }
    }
    return len;
}

/* 逐层打印 + 返回队列峰值（= 最大层宽 w），用来印证空间是 O(w) 不是 O(h) */
static int levelByLevel(BiTree t)
{
    BiTree q[MAXN];
    int front = 0, rear = 0, level = 1, peak = 0;

    if (t == NULL) {
        printf("  (空树)\n");
        return 0;
    }
    q[rear++] = t;
    while (front < rear) {
        int levelSize = rear - front;   /* ★ 必须在出队任何元素之前取 */
        int k;

        if (levelSize > peak) {
            peak = levelSize;
        }
        printf("  第%d层(%d个):", level, levelSize);
        for (k = 0; k < levelSize; k++) {
            BiTree p = q[front++];

            printf(" %c", p->data);
            if (p->lchild != NULL) {
                q[rear++] = p->lchild;
            }
            if (p->rchild != NULL) {
                q[rear++] = p->rchild;
            }
        }
        printf("\n");
        level++;
    }
    return peak;
}

/* BFS 求高：每处理完一整层 h 加 1 */
static int heightBFS(BiTree t)
{
    BiTree q[MAXN];
    int front = 0, rear = 0, h = 0;

    if (t == NULL) {
        return 0;
    }
    q[rear++] = t;
    while (front < rear) {
        int levelSize = rear - front, k;

        for (k = 0; k < levelSize; k++) {
            BiTree p = q[front++];

            if (p->lchild != NULL) {
                q[rear++] = p->lchild;
            }
            if (p->rchild != NULL) {
                q[rear++] = p->rchild;
            }
        }
        h++;
    }
    return h;
}

/* 递归求高，用来与 BFS 结果交叉验证 */
static int heightDFS(BiTree t)
{
    int hl, hr;

    if (t == NULL) {
        return 0;
    }
    hl = heightDFS(t->lchild);
    hr = heightDFS(t->rchild);
    return (hl > hr ? hl : hr) + 1;
}

/* BFS 首次到达 target 的层数（根在第 1 层）；找不到返回 0 */
static int depthOfNode(BiTree t, char target)
{
    BiTree q[MAXN];
    int front = 0, rear = 0, level = 1;

    if (t == NULL) {
        return 0;
    }
    q[rear++] = t;
    while (front < rear) {
        int levelSize = rear - front, k;

        for (k = 0; k < levelSize; k++) {
            BiTree p = q[front++];

            if (p->data == target) {
                return level;
            }
            if (p->lchild != NULL) {
                q[rear++] = p->lchild;
            }
            if (p->rchild != NULL) {
                q[rear++] = p->rchild;
            }
        }
        level++;
    }
    return 0;
}

int main(void)
{
    const char *pres[] = { "ABD##E##CF##G##", "ABD##E##C#F##", "ABC####", "#" };
    const char *desc[] = { "满二叉树(7结点)", "普通二叉树(6结点)", "左斜链(单支树)", "空树" };
    int k;

    printf("== 四种树形的层次遍历与逐层打印 ==\n");
    for (k = 0; k < 4; k++) {
        BiTree t = NULL;
        char seq[MAXN];
        int i = 0, len, j, peak;

        createBiTree(&t, pres[k], &i);
        len = levelOrder(t, seq);
        printf("树%d [%s] 先序串=%s 结点数=%d\n", k + 1, desc[k], pres[k], len);
        printf("  层次序列:");
        if (len == 0) {
            printf(" (空)");
        }
        for (j = 0; j < len; j++) {
            printf(" %c", seq[j]);
        }
        printf("\n");
        peak = levelByLevel(t);
        printf("  BFS求高=%d  递归求高=%d  相符=%d  队列峰值(最大层宽w)=%d\n",
               heightBFS(t), heightDFS(t), heightBFS(t) == heightDFS(t), peak);
        printf("\n");
        destroyBiTree(&t);
    }

    printf("== BFS 层数 = 根到该结点的路径长度（无权图最短距离 + 1）==\n");
    {
        BiTree t = NULL;
        int i = 0;

        createBiTree(&t, "ABD##E##CF##G##", &i);
        printf("满二叉树 ABD##E##CF##G## 上：\n");
        printf("  到A的层数=%d 到B=%d 到D=%d 到E=%d 到C=%d 到F=%d 到G=%d\n",
               depthOfNode(t, 'A'), depthOfNode(t, 'B'), depthOfNode(t, 'D'),
               depthOfNode(t, 'E'), depthOfNode(t, 'C'), depthOfNode(t, 'F'),
               depthOfNode(t, 'G'));
        printf("  到不存在的 X 的层数=%d（0 表示未找到）\n", depthOfNode(t, 'X'));
        destroyBiTree(&t);
    }

    printf("\n== 单支树上 BFS 层数与深度优先的差别 ==\n");
    {
        BiTree t = NULL;
        int i = 0;

        createBiTree(&t, "ABC####", &i);
        printf("左斜链 ABC#### 上：到A=%d 到B=%d 到C=%d（队列峰值只有 1）\n",
               depthOfNode(t, 'A'), depthOfNode(t, 'B'), depthOfNode(t, 'C'));
        destroyBiTree(&t);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 32

typedef struct BiTNode {
    char data;
    struct BiTNode *lchild, *rchild;
} BiTNode, *BiTree;

/* 先序 + 中序 重建 */
static BiTree buildPreIn(const char *pre, int preL, int preR,
                         const char *in, int inL, int inR)
{
    int k, leftSize;
    BiTree t;

    if (preL > preR) {
        return NULL;
    }
    t = (BiTree)malloc(sizeof(BiTNode));
    t->data = pre[preL];                  /* ① 先序首元素是根 */
    for (k = inL; k <= inR; k++) {        /* ② 在中序里定位根 */
        if (in[k] == pre[preL]) {
            break;
        }
    }
    leftSize = k - inL;                   /* ③ 根左边个数 = 左子树大小 */
    t->lchild = buildPreIn(pre, preL + 1, preL + leftSize, in, inL, k - 1);
    t->rchild = buildPreIn(pre, preL + leftSize + 1, preR, in, k + 1, inR);
    return t;
}

/* 后序 + 中序 重建：唯一区别是根在 post[postR] */
static BiTree buildPostIn(const char *post, int postL, int postR,
                          const char *in, int inL, int inR)
{
    int k, leftSize;
    BiTree t;

    if (postL > postR) {
        return NULL;
    }
    t = (BiTree)malloc(sizeof(BiTNode));
    t->data = post[postR];                /* ★ 根在后序末尾 */
    for (k = inL; k <= inR; k++) {
        if (in[k] == post[postR]) {
            break;
        }
    }
    leftSize = k - inL;
    t->lchild = buildPostIn(post, postL, postL + leftSize - 1, in, inL, k - 1);
    t->rchild = buildPostIn(post, postL + leftSize, postR - 1, in, k + 1, inR);
    return t;
}

static void destroyBiTree(BiTree *T)
{
    if (*T == NULL) {
        return;
    }
    destroyBiTree(&(*T)->lchild);
    destroyBiTree(&(*T)->rchild);
    free(*T);
    *T = NULL;
}

static void preorder(BiTree t, char *out, int *len)
{
    if (t == NULL) {
        return;
    }
    out[(*len)++] = t->data;
    preorder(t->lchild, out, len);
    preorder(t->rchild, out, len);
}

static void inorder(BiTree t, char *out, int *len)
{
    if (t == NULL) {
        return;
    }
    inorder(t->lchild, out, len);
    out[(*len)++] = t->data;
    inorder(t->rchild, out, len);
}

static void postorder(BiTree t, char *out, int *len)
{
    if (t == NULL) {
        return;
    }
    postorder(t->lchild, out, len);
    postorder(t->rchild, out, len);
    out[(*len)++] = t->data;
}

static void printSeq(const char *s, int len)
{
    int i;

    if (len == 0) {
        printf("(空)");
        return;
    }
    for (i = 0; i < len; i++) {
        printf("%c", s[i]);
    }
}

/* 打印结构骨架：根(左子树,右子树)，空子树用 - 表示 */
static void printShape(BiTree t)
{
    if (t == NULL) {
        printf("-");
        return;
    }
    printf("%c(", t->data);
    printShape(t->lchild);
    printf(",");
    printShape(t->rchild);
    printf(")");
}

int main(void)
{
    char a[MAXN], b[MAXN], c[MAXN];
    int la, lb, lc;
    BiTree t;

    printf("== 例1：先序 ABDECFG + 中序 DBEAFCG 重建 ==\n");
    t = buildPreIn("ABDECFG", 0, 6, "DBEAFCG", 0, 6);
    la = lb = lc = 0;
    preorder(t, a, &la);
    inorder(t, b, &lb);
    postorder(t, c, &lc);
    printf("  结构: ");
    printShape(t);
    printf("\n  重建后先序=");
    printSeq(a, la);
    printf(" 与原先序一致=%d\n", strncmp(a, "ABDECFG", la) == 0);
    printf("  重建后中序=");
    printSeq(b, lb);
    printf(" 与原中序一致=%d\n", strncmp(b, "DBEAFCG", lb) == 0);
    printf("  推出的后序=");
    printSeq(c, lc);
    printf("\n");
    destroyBiTree(&t);

    printf("\n== 例2：后序 DEBFGCA + 中序 DBEAFCG 重建（应得到同一棵树）==\n");
    t = buildPostIn("DEBFGCA", 0, 6, "DBEAFCG", 0, 6);
    la = lb = 0;
    preorder(t, a, &la);
    inorder(t, b, &lb);
    printf("  结构: ");
    printShape(t);
    printf("\n  重建后先序=");
    printSeq(a, la);
    printf(" 应为 ABDECFG，一致=%d\n", strncmp(a, "ABDECFG", la) == 0);
    printf("  重建后中序=");
    printSeq(b, lb);
    printf(" 一致=%d\n", strncmp(b, "DBEAFCG", lb) == 0);
    destroyBiTree(&t);

    printf("\n== 例3：先序+后序不唯一的最小反例 ==\n");
    printf("树1 = A(B,-)  先序=AB 后序=BA 中序=BA\n");
    printf("树2 = A(-,B)  先序=AB 后序=BA 中序=AB\n");
    t = buildPreIn("AB", 0, 1, "BA", 0, 1);
    printf("用中序 BA 重建 → 结构: ");
    printShape(t);
    la = lc = 0;
    preorder(t, a, &la);
    postorder(t, c, &lc);
    printf("  先序=");
    printSeq(a, la);
    printf(" 后序=");
    printSeq(c, lc);
    printf("\n");
    destroyBiTree(&t);

    t = buildPreIn("AB", 0, 1, "AB", 0, 1);
    printf("用中序 AB 重建 → 结构: ");
    printShape(t);
    la = lc = 0;
    preorder(t, a, &la);
    postorder(t, c, &lc);
    printf("  先序=");
    printSeq(a, la);
    printf(" 后序=");
    printSeq(c, lc);
    printf("\n");
    printf("两棵树的先序与后序完全相同，结构却不同 → 必须有中序才能区分\n");
    destroyBiTree(&t);

    printf("\n== 例4：左斜链与右斜链（先序相同、中序相反）==\n");
    t = buildPreIn("ABC", 0, 2, "CBA", 0, 2);
    printf("先序ABC+中序CBA → 结构: ");
    printShape(t);
    printf("\n");
    destroyBiTree(&t);
    t = buildPreIn("ABC", 0, 2, "ABC", 0, 2);
    printf("先序ABC+中序ABC → 结构: ");
    printShape(t);
    printf("\n");
    destroyBiTree(&t);
    return 0;
}

