#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef enum { LINK, THREAD } PointerTag;

typedef struct ThreadNode {
    char data;
    struct ThreadNode *lchild, *rchild;
    PointerTag ltag, rtag;
} ThreadNode, *ThreadTree;

static void createBiTree(ThreadTree *T, const char *pre, int *i)
{
    char c = pre[*i];

    if (c == '\0' || c == '#') {
        *T = NULL;
        if (c != '\0') {
            (*i)++;
        }
        return;
    }
    (*i)++;
    *T = (ThreadTree)malloc(sizeof(ThreadNode));
    (*T)->data = c;
    (*T)->ltag = LINK;
    (*T)->rtag = LINK;
    createBiTree(&(*T)->lchild, pre, i);
    createBiTree(&(*T)->rchild, pre, i);
}

/* 中序线索化：pre 用指针传参，保证整棵子树共享同一个前驱 */
static void inThreading(ThreadTree t, ThreadTree *pre)
{
    if (t == NULL) {
        return;
    }
    inThreading(t->lchild, pre);
    if (t->lchild == NULL) {              /* 左空 → 指前驱 */
        t->ltag = THREAD;
        t->lchild = *pre;
    }
    if (*pre != NULL && (*pre)->rchild == NULL) {   /* 前驱的右空 → 指当前 */
        (*pre)->rtag = THREAD;
        (*pre)->rchild = t;
    }
    *pre = t;
    inThreading(t->rchild, pre);
}

/* 返回头结点；thrt->lchild 指根，thrt->rchild 指中序最后一个结点 */
static ThreadTree inOrderThreading(ThreadTree t)
{
    ThreadTree thrt = (ThreadTree)malloc(sizeof(ThreadNode));
    ThreadTree pre;

    thrt->data = '#';
    thrt->ltag = LINK;
    thrt->rtag = THREAD;
    thrt->rchild = thrt;                  /* 先指回自己，空树时正好 */
    if (t == NULL) {
        thrt->lchild = thrt;
        return thrt;
    }
    thrt->lchild = t;
    pre = thrt;                           /* ★ 初始前驱是头结点 */
    inThreading(t, &pre);
    pre->rchild = thrt;                   /* 最后一个结点 → 头结点 */
    pre->rtag = THREAD;
    thrt->rchild = pre;                   /* 头结点 → 最后一个结点 */
    return thrt;
}

/* 沿线索收集中序序列：不用栈、不用递归。
   ★ 三段式：先向左下探到最左 → 访问 → 沿右线索连续访问后继 → 最后转入右子树（LINK）
   只写「向左下探 + p = p->rchild」两句是错的：遇到 rtag==LINK 的结点会退回已访问过的祖先 */
static int collectInOrder(ThreadTree thrt, ThreadTree *out)
{
    ThreadTree p = thrt->lchild;
    int len = 0;

    while (p != thrt) {                       /* 走回头结点表示遍历结束 */
        while (p->ltag == LINK) {
            p = p->lchild;
        }
        out[len++] = p;
        while (p->rtag == THREAD && p->rchild != thrt) {
            p = p->rchild;                    /* 沿右线索连续前进 */
            out[len++] = p;
        }
        p = p->rchild;                        /* 转入右子树，或正好是头结点而结束 */
    }
    return len;
}

static int inOrderThreaded(ThreadTree thrt, char *out)
{
    ThreadTree nodes[64];
    int len = collectInOrder(thrt, nodes), i;

    for (i = 0; i < len; i++) {
        out[i] = nodes[i]->data;
    }
    return len;
}

/* 线索化后 LINK 标志的父子指针仍在，可以按普通二叉树后序释放；
   注意必须靠 tag 判断能不能递归——线索指针指向的结点不属于本树，跟着走会 double free */
static void destroyTree(ThreadTree t)
{
    if (t == NULL) {
        return;
    }
    if (t->ltag == LINK) {
        destroyTree(t->lchild);
    }
    if (t->rtag == LINK) {
        destroyTree(t->rchild);
    }
    free(t);
}

/* 按 LINK 关系遍历原树，统计 2n 个指针域里有多少是线索、多少是真链 */
static void countTree(ThreadTree t, int *threads, int *links, int *nodes)
{
    if (t == NULL) {
        return;
    }
    (*nodes)++;
    if (t->ltag == THREAD) {
        (*threads)++;
    } else {
        (*links)++;
    }
    if (t->rtag == THREAD) {
        (*threads)++;
    } else {
        (*links)++;
    }
    if (t->ltag == LINK) {
        countTree(t->lchild, threads, links, nodes);
    }
    if (t->rtag == LINK) {
        countTree(t->rchild, threads, links, nodes);
    }
}

static void describeTarget(ThreadTree thrt, ThreadTree x, char *buf, int cap)
{
    if (x == thrt) {
        snprintf(buf, (size_t)cap, "头结点");
    } else if (x == NULL) {
        snprintf(buf, (size_t)cap, "NULL");
    } else {
        snprintf(buf, (size_t)cap, "%c", x->data);
    }
}

static void dumpThreads(ThreadTree thrt)
{
    ThreadTree nodes[64];
    char lb[16], rb[16];
    int len = collectInOrder(thrt, nodes), i;

    for (i = 0; i < len; i++) {
        describeTarget(thrt, nodes[i]->lchild, lb, (int)sizeof lb);
        describeTarget(thrt, nodes[i]->rchild, rb, (int)sizeof rb);
        printf("  %c: ltag=%s lchild=%s | rtag=%s rchild=%s\n",
               nodes[i]->data,
               nodes[i]->ltag == THREAD ? "线索" : "链", lb,
               nodes[i]->rtag == THREAD ? "线索" : "链", rb);
    }
}

int main(void)
{
    const char *pres[] = { "ABD##E##CF##G##", "AB##C##", "ABC####", "#" };
    const char *desc[] = { "满二叉树(7结点)", "3结点满二叉树", "左斜链(3结点)", "空树" };
    int k;

    for (k = 0; k < 4; k++) {
        ThreadTree t = NULL, thrt;
        char seq[64], lbuf[16], rbuf[16];
        int i = 0, len, threads = 0, links = 0, nodes = 0, j;

        createBiTree(&t, pres[k], &i);
        thrt = inOrderThreading(t);
        len = inOrderThreaded(thrt, seq);
        countTree(t, &threads, &links, &nodes);

        printf("树%d [%s] 先序串=%s\n", k + 1, desc[k], pres[k]);
        printf("  结点数 n=%d  指针域总数 2n=%d  真实边 n-1=%d\n",
               nodes, 2 * nodes, nodes > 0 ? nodes - 1 : 0);
        if (nodes == 0) {
            printf("  空树无线索可建（线索数=0 链数=0）\n");
        } else {
            printf("  线索数=%d  真链数=%d  两者之和=%d  线索数==n+1 ? %d\n",
                   threads, links, threads + links, threads == nodes + 1);
        }
        printf("  沿线索中序遍历:");
        if (len == 0) {
            printf(" (空)");
        }
        for (j = 0; j < len; j++) {
            printf(" %c", seq[j]);
        }
        printf("\n");
        describeTarget(thrt, thrt->lchild, lbuf, (int)sizeof lbuf);
        describeTarget(thrt, thrt->rchild, rbuf, (int)sizeof rbuf);
        printf("  头结点: ltag=%s lchild→%s | rtag=%s rchild→%s\n",
               thrt->ltag == LINK ? "链" : "线索", lbuf,
               thrt->rtag == LINK ? "链" : "线索", rbuf);
        if (nodes > 0) {
            printf("  逐结点线索明细:\n");
            dumpThreads(thrt);
        }
        printf("\n");

        destroyTree(t);
        free(thrt);
    }
    return 0;
}

