#include <stdio.h>
#include <stdlib.h>

typedef enum { LINK, THREAD } PointerTag;

typedef struct ThreadNode {
    char data;
    struct ThreadNode *lchild, *rchild;
    PointerTag ltag, rtag;
} ThreadNode, *ThreadTree;

static void createBiTree(ThreadTree *T, const char *pre, int *i)
{
    char c = pre[*i];

    if (c == '\0' || c == '#') {
        *T = NULL;
        if (c != '\0') {
            (*i)++;
        }
        return;
    }
    (*i)++;
    *T = (ThreadTree)malloc(sizeof(ThreadNode));
    (*T)->data = c;
    (*T)->ltag = LINK;
    (*T)->rtag = LINK;
    createBiTree(&(*T)->lchild, pre, i);
    createBiTree(&(*T)->rchild, pre, i);
}

static void inThreading(ThreadTree t, ThreadTree *pre)
{
    if (t == NULL) {
        return;
    }
    inThreading(t->lchild, pre);
    if (t->lchild == NULL) {
        t->ltag = THREAD;
        t->lchild = *pre;
    }
    if (*pre != NULL && (*pre)->rchild == NULL) {
        (*pre)->rtag = THREAD;
        (*pre)->rchild = t;
    }
    *pre = t;
    inThreading(t->rchild, pre);
}

static ThreadTree inOrderThreading(ThreadTree t)
{
    ThreadTree thrt = (ThreadTree)malloc(sizeof(ThreadNode));
    ThreadTree pre;

    thrt->data = '#';
    thrt->ltag = LINK;
    thrt->rtag = THREAD;
    thrt->rchild = thrt;
    if (t == NULL) {
        thrt->lchild = thrt;
        return thrt;
    }
    thrt->lchild = t;
    pre = thrt;
    inThreading(t, &pre);
    pre->rchild = thrt;
    pre->rtag = THREAD;
    thrt->rchild = pre;
    return thrt;
}

static void destroyTree(ThreadTree t)
{
    if (t == NULL) {
        return;
    }
    if (t->ltag == LINK) {
        destroyTree(t->lchild);
    }
    if (t->rtag == LINK) {
        destroyTree(t->rchild);
    }
    free(t);
}

/* 中序后继：rtag 是线索时 O(1)，是链时下探到右子树最左下 */
static ThreadTree inNext(ThreadTree p, int *steps)
{
    *steps = 0;
    if (p->rtag == THREAD) {
        return p->rchild;
    }
    p = p->rchild;
    (*steps)++;
    while (p->ltag == LINK) {
        p = p->lchild;
        (*steps)++;
    }
    return p;
}

/* 中序前驱：ltag 是线索时 O(1)，是链时下探到左子树最右下 */
static ThreadTree inPrev(ThreadTree p, int *steps)
{
    *steps = 0;
    if (p->ltag == THREAD) {
        return p->lchild;
    }
    p = p->lchild;
    (*steps)++;
    while (p->rtag == LINK) {
        p = p->rchild;
        (*steps)++;
    }
    return p;
}

/* 中序第一个结点：从根一路向左下探 */
static ThreadTree inFirst(ThreadTree thrt)
{
    ThreadTree p = thrt->lchild;

    while (p != thrt && p->ltag == LINK) {
        p = p->lchild;
    }
    return p;
}

static void describeTarget(ThreadTree thrt, ThreadTree x, char *buf, int cap)
{
    if (x == thrt) {
        snprintf(buf, (size_t)cap, "#头结点");
    } else if (x == NULL) {
        snprintf(buf, (size_t)cap, "NULL");
    } else {
        snprintf(buf, (size_t)cap, "%c", x->data);
    }
}

int main(void)
{
    const char *pres[] = { "ABD##E##CF##G##", "AB##C##", "ABC####", "#" };
    const char *desc[] = { "满二叉树(7结点)", "3结点满二叉树", "左斜链(3结点)", "空树" };
    int k;

    for (k = 0; k < 4; k++) {
        ThreadTree t = NULL, thrt, p;
        char lbuf[16], rbuf[16];
        int i = 0, steps;

        createBiTree(&t, pres[k], &i);
        thrt = inOrderThreading(t);

        printf("树%d [%s] 先序串=%s\n", k + 1, desc[k], pres[k]);

        printf("  正向中序(inNext 走):");
        for (p = inFirst(thrt); p != thrt; p = inNext(p, &steps)) {
            printf(" %c", p->data);
        }
        printf("\n");

        printf("  逆向中序(inPrev 走):");
        for (p = thrt->rchild; p != thrt; p = inPrev(p, &steps)) {
            printf(" %c", p->data);
        }
        printf("\n");

        if (t != NULL) {
            printf("  逐结点前驱/后继与查询步数:\n");
            for (p = inFirst(thrt); p != thrt; p = inNext(p, &steps)) {
                ThreadTree nx, pv;
                int sn, sp;

                nx = inNext(p, &sn);
                pv = inPrev(p, &sp);
                describeTarget(thrt, pv, lbuf, (int)sizeof lbuf);
                describeTarget(thrt, nx, rbuf, (int)sizeof rbuf);
                printf("    %c: 前驱=%s(步%d) 后继=%s(步%d) rtag=%s\n",
                       p->data, lbuf, sp, rbuf, sn,
                       p->rtag == THREAD ? "线索" : "链");
            }
        }
        printf("  遍历辅助空间=O(1)（两个指针变量，无栈无递归）\n\n");
        destroyTree(t);
        free(thrt);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MAX_TREE 16

/* ---------- 方式一：双亲表示法 ---------- */
typedef struct {
    char data;
    int parent;                  /* 双亲下标，根为 -1 */
} PNode;

/* ---------- 方式二：孩子表示法 ---------- */
typedef struct ChildNode {
    int idx;
    struct ChildNode *next;
} ChildNode;

typedef struct {
    char data;
    ChildNode *firstChild;
} CNode;

/* ---------- 方式三：孩子兄弟表示法 ---------- */
typedef struct CSNode {
    char data;
    struct CSNode *firstChild, *nextSibling;
} CSNode, *CSTree;

static PNode pnodes[MAX_TREE];
static CNode cnodes[MAX_TREE];
static int nodeCount = 0;

static void addNode(char c)
{
    pnodes[nodeCount].data = c;
    pnodes[nodeCount].parent = -1;
    cnodes[nodeCount].data = c;
    cnodes[nodeCount].firstChild = NULL;
    nodeCount++;
}

static void setParent(int child, int parent)
{
    pnodes[child].parent = parent;
}

/* 尾插到孩子链表末尾，保持孩子的输入次序（有序树） */
static void addChild(int parentIdx, int childIdx)
{
    ChildNode *p = (ChildNode *)malloc(sizeof(ChildNode));
    ChildNode *q;

    p->idx = childIdx;
    p->next = NULL;
    if (cnodes[parentIdx].firstChild == NULL) {
        cnodes[parentIdx].firstChild = p;
        return;
    }
    for (q = cnodes[parentIdx].firstChild; q->next != NULL; q = q->next) {
        ;                          /* 走到链表尾 */
    }
    q->next = p;
}

/* 找双亲 O(1)：直接读 parent 域 */
static int findParentByArray(char target, int *visited)
{
    int i;

    *visited = 0;
    for (i = 0; i < nodeCount; i++) {
        (*visited)++;
        if (pnodes[i].data == target) {
            return pnodes[i].parent;
        }
    }
    return -1;
}

/* 找孩子 O(n)：必须扫描全表 */
static void findChildrenByArray(char target, int *visited)
{
    int i, idx = -1;

    *visited = 0;
    for (i = 0; i < nodeCount; i++) {
        (*visited)++;
        if (pnodes[i].data == target) {
            idx = i;
        }
    }
    printf("  求 %c 的所有孩子：扫描全表 -> 访问结点数=%d，结果", target, *visited);
    {
        int found = 0;

        for (i = 0; i < nodeCount; i++) {
            if (pnodes[i].parent == idx) {
                printf(" %c", pnodes[i].data);
                found = 1;
            }
        }
        if (!found) {
            printf(" (无)");
        }
    }
    printf("\n");
}

/* 找双亲 O(n)：必须遍历所有孩子链表 */
static int findParentByChildList(char target, int *edgesScanned)
{
    int i;

    *edgesScanned = 0;
    for (i = 0; i < nodeCount; i++) {
        ChildNode *q;

        for (q = cnodes[i].firstChild; q != NULL; q = q->next) {
            (*edgesScanned)++;
            if (cnodes[q->idx].data == target) {
                return i;
            }
        }
    }
    return -1;
}

static CSTree mkCS(char c, CSTree firstChild, CSTree nextSibling)
{
    CSTree p = (CSTree)malloc(sizeof(CSNode));

    p->data = c;
    p->firstChild = firstChild;
    p->nextSibling = nextSibling;
    return p;
}

/* 孩子兄弟表示法就是二叉树：firstChild 当 lchild、nextSibling 当 rchild */
static void csPreorder(CSTree t, char *out, int *len)
{
    if (t == NULL) {
        return;
    }
    out[(*len)++] = t->data;
    csPreorder(t->firstChild, out, len);
    csPreorder(t->nextSibling, out, len);
}

static void csInorder(CSTree t, char *out, int *len)
{
    if (t == NULL) {
        return;
    }
    csInorder(t->firstChild, out, len);
    out[(*len)++] = t->data;
    csInorder(t->nextSibling, out, len);
}

/* 直接在原树上做后根遍历：先依次后根遍历各子树，再访问根 */
static void postRootTree(int idx, char *out, int *len)
{
    ChildNode *q;

    for (q = cnodes[idx].firstChild; q != NULL; q = q->next) {
        postRootTree(q->idx, out, len);
    }
    out[(*len)++] = cnodes[idx].data;
}

static void printSeq(const char *s, int len)
{
    int i;

    if (len == 0) {
        printf("(空)");
        return;
    }
    for (i = 0; i < len; i++) {
        printf("%c%s", s[i], i + 1 < len ? " " : "");
    }
}

static void freeChildLists(void)
{
    int i;

    for (i = 0; i < nodeCount; i++) {
        ChildNode *q = cnodes[i].firstChild, *next;

        while (q != NULL) {
            next = q->next;          /* ★ 先存住 next 再 free */
            free(q);
            q = next;
        }
        cnodes[i].firstChild = NULL;
    }
}

static void destroyCS(CSTree t)
{
    if (t == NULL) {
        return;
    }
    destroyCS(t->firstChild);
    destroyCS(t->nextSibling);
    free(t);
}

int main(void)
{
    char seq[32];
    int len, visited, edges, idx;
    CSTree csTree;

    /* 建树 A(B(E,F), C, D(G))，下标 0..6 */
    addNode('A');  addNode('B');  addNode('C');  addNode('D');
    addNode('E');  addNode('F');  addNode('G');
    setParent(1, 0);  setParent(2, 0);  setParent(3, 0);
    setParent(4, 1);  setParent(5, 1);  setParent(6, 3);
    addChild(0, 1);  addChild(0, 2);  addChild(0, 3);
    addChild(1, 4);  addChild(1, 5);
    addChild(3, 6);

    printf("原树 A(B(E,F),C,D(G))，共 %d 个结点\n\n", nodeCount);

    printf("== 方式一 双亲表示法：找双亲 O(1)，找孩子 O(n) ==\n");
    for (idx = 0; idx < nodeCount; idx++) {
        printf("  下标 %d data=%c parent=%d%s\n", idx, pnodes[idx].data,
               pnodes[idx].parent, pnodes[idx].parent == -1 ? "（根）" : "");
    }
    idx = findParentByArray('G', &visited);
    printf("  求 G 的双亲：按 data 定位结点扫描 %d 个，定位后读 parent 域只需 1 次 -> 下标 %d = %c\n",
           visited, idx, pnodes[idx].data);
    findChildrenByArray('A', &visited);
    findChildrenByArray('C', &visited);

    printf("\n== 方式二 孩子表示法：找孩子 O(度)，找双亲 O(n) ==\n");
    for (idx = 0; idx < nodeCount; idx++) {
        ChildNode *q;

        printf("  %c ->", cnodes[idx].data);
        if (cnodes[idx].firstChild == NULL) {
            printf(" (无孩子)");
        }
        for (q = cnodes[idx].firstChild; q != NULL; q = q->next) {
            printf(" %c", cnodes[q->idx].data);
        }
        printf("\n");
    }
    idx = findParentByChildList('G', &edges);
    printf("  求 G 的双亲：遍历所有孩子链表 -> 检查边数=%d，结果 %c\n",
           edges, cnodes[idx].data);
    printf("  求 D 的孩子：直接沿 firstChild 走 -> 结果");
    {
        ChildNode *q;
        int steps = 0;

        for (q = cnodes[3].firstChild; q != NULL; q = q->next) {
            printf(" %c", cnodes[q->idx].data);
            steps++;
        }
        printf("，步数=%d\n", steps);
    }

    printf("\n== 方式三 孩子兄弟表示法：与二叉树一一对应 ==\n");
    csTree = mkCS('A',
                  mkCS('B',
                       mkCS('E', NULL, mkCS('F', NULL, NULL)),
                       mkCS('C', NULL,
                            mkCS('D', mkCS('G', NULL, NULL), NULL))),
                  NULL);
    {
        CSTree stack[16];
        int top = -1;

        stack[++top] = csTree;
        while (top >= 0) {                 /* 用栈枚举所有结点，保证输出次序稳定 */
            CSTree p = stack[top--];

            printf("  %c: firstChild=%c nextSibling=%c\n", p->data,
                   p->firstChild ? p->firstChild->data : '-',
                   p->nextSibling ? p->nextSibling->data : '-');
            if (p->nextSibling) {
                stack[++top] = p->nextSibling;
            }
            if (p->firstChild) {
                stack[++top] = p->firstChild;
            }
        }
    }
    printf("  根的 nextSibling = %s（原树根没有兄弟，转换后必为空）\n",
           csTree->nextSibling ? "非空" : "空");

    printf("\n== 遍历对应关系验证 ==\n");
    len = 0;
    csPreorder(csTree, seq, &len);
    printf("  孩子兄弟表示法的先序 = ");
    printSeq(seq, len);
    printf("   <- 这就是原树的【先根遍历】\n");

    len = 0;
    csInorder(csTree, seq, &len);
    printf("  孩子兄弟表示法的中序 = ");
    printSeq(seq, len);
    printf("   <- 对应原树的【后根遍历】\n");

    len = 0;
    postRootTree(0, seq, &len);
    printf("  原树直接后根遍历     = ");
    printSeq(seq, len);
    printf("\n");

    freeChildLists();
    destroyCS(csTree);
    printf("\n三种存储的内存均已释放\n");
    return 0;
}
